use novel_storage::{Storage,Scene,SyncCursor};
use serde_json::{json,Value};
fn scene(text:&str)->Scene {Scene{schema_version:1,title:"Synthetic scene".into(),document:json!({"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":text}]}]})}}
async fn setup()->(tempfile::TempDir,Storage,String,String,String){let d=tempfile::tempdir().unwrap();let s=Storage::open(&d.path().join("notes.sqlite")).await.unwrap();let p=s.create_project("Notebook fixture").await.unwrap();let c=s.create_chapter(&p.id,"Chapter 1").await.unwrap();let x=s.create_scene(&c.id,scene("A 世界 😀 مَرْحَبًا")).await.unwrap();(d,s,p.id,x.id,x.revision_id)}
fn payload(sid:&str,rid:&str)->Value {json!({"schemaVersion":1,"scraps":[{"id":"cut","sceneId":sid,"text":"Deleted مَرْحَبًا\n世界 😀"}],"reactions":[{"id":"reaction","sceneId":sid,"revisionId":rid,"quote":"世界 😀","start":2,"kind":"curious","resolved":false}],"bookmarks":[{"id":"return","sceneId":sid,"note":"Next, discover the letter 世界","location":{"documentHash":"a".repeat(64),"cursor":[0,4],"anchor":[0,4]}}],"notes":[{"id":"note","sceneId":sid,"text":"Clarify the promise مَرْحَبًا","resolved":false}]})}
#[tokio::test] async fn notebook_tools_roundtrip_cas_history_and_reopen(){
 let(d,s,p,sid,rid)=setup().await;let original=payload(&sid,&rid);let one=s.save_project_data(&p,"notebookTools",original.clone(),None).await.unwrap();let mut next=original.clone();next["notes"][0]["resolved"]=json!(true);let two=s.save_project_data(&p,"notebookTools",next.clone(),Some(one.revision_id.clone())).await.unwrap();
 assert!(s.save_project_data(&p,"notebookTools",original.clone(),Some(one.revision_id.clone())).await.unwrap_err().contains("Conflict"));assert_eq!(s.load_project_data_revision(&p,"notebookTools",&one.revision_id).await.unwrap().payload,original);assert_eq!(s.project_data_history(&p,"notebookTools").await.unwrap().len(),2);
 // Source revision stays valid after the manuscript changes; no stale offset is retargeted.
 s.save_scene(&sid,scene("Entirely rewritten"),Some(rid)).await.unwrap();s.close().await;let s=Storage::open(&d.path().join("notes.sqlite")).await.unwrap();assert_eq!(s.load_project_data(&p,"notebookTools").await.unwrap().unwrap(),two);
}
#[tokio::test] async fn notebook_tools_archive_and_branch_remap_scene_revision_but_keep_text_and_hash(){
 let(_d,s,p,sid,rid)=setup().await;let data=payload(&sid,&rid);s.save_project_data(&p,"notebookTools",data.clone(),None).await.unwrap();let archive=s.export_archive(&p).await.unwrap();let imported=s.import_archive(&archive).await.unwrap();let branch=s.create_project_branch(&p,"Alternative").await.unwrap();
 for pid in [&imported.project.id,&branch.project_id]{let bundle=s.open_project(pid).await.unwrap();let copied=s.load_project_data(pid,"notebookTools").await.unwrap().unwrap().payload;for key in ["scraps","reactions","bookmarks","notes"]{assert_eq!(copied[key][0]["sceneId"],bundle.scenes[0].id);assert_ne!(copied[key][0]["sceneId"],sid);}assert_eq!(copied["reactions"][0]["revisionId"],bundle.scenes[0].revision_id);assert_ne!(copied["reactions"][0]["revisionId"],rid);assert_eq!(copied["reactions"][0]["quote"],data["reactions"][0]["quote"]);assert_eq!(copied["bookmarks"][0]["location"],data["bookmarks"][0]["location"]);assert_eq!(copied["scraps"][0]["text"],data["scraps"][0]["text"]);}
}
#[tokio::test] async fn notebook_tools_reject_bad_shape_foreign_scenes_and_forged_quotes(){
 let(_d,s,p,sid,rid)=setup().await;let data=payload(&sid,&rid);let foreign=s.create_novel("Other novel").await.unwrap();
 let mut bad=Vec::new();let mut v=data.clone();v["notes"][0]["id"]=json!("cut");bad.push(v);let mut v=data.clone();v["bookmarks"][0]["location"]["cursor"]=json!([0,-1]);bad.push(v);let mut v=data.clone();v["bookmarks"][0]["location"]["documentHash"]=json!("short");bad.push(v);let mut v=data.clone();v["notes"][0]["sceneId"]=json!(foreign.scene.id);bad.push(v);let mut v=data.clone();v["reactions"][0]["revisionId"]=json!(foreign.scene.revision_id);bad.push(v);let mut v=data.clone();v["reactions"][0]["start"]=json!(3);bad.push(v);let mut v=data.clone();v["reactions"][0]["quote"]=json!("invented");bad.push(v);let mut v=data.clone();v["reactions"][0]["kind"]=json!("unrecognized");bad.push(v);let mut v=data.clone();v["notes"][0]["resolved"]=Value::Null;bad.push(v);let mut v=data.clone();v["scraps"][0]["text"]=json!("");bad.push(v);let mut v=data.clone();v["bookmarks"].as_array_mut().unwrap().push(data["bookmarks"][0].clone());v["bookmarks"][1]["id"]=json!("second-bookmark");bad.push(v);
 let cursor=s.sync_cursor().await.unwrap();for value in bad{assert!(s.save_project_data(&p,"notebookTools",value,None).await.is_err());assert_eq!(s.sync_cursor().await.unwrap(),cursor);}assert!(s.load_project_data(&p,"notebookTools").await.unwrap().is_none());assert_eq!(s.save_project_data(&p,"notebookTools",data.clone(),None).await.unwrap().payload,data);
}
#[tokio::test] async fn notebook_tools_sync_validates_sources_and_refuses_save_over_competing_heads(){
 use sha2::{Digest,Sha256};
 let(_d,s,p,sid,rid)=setup().await;let data=payload(&sid,&rid);let saved=s.save_project_data(&p,"notebookTools",data.clone(),None).await.unwrap();let source=s.sync_cursor().await.unwrap();let page=s.pull_revisions(&p,SyncCursor{epoch:source.epoch.clone(),sequence:0},1000).await.unwrap();let d=tempfile::tempdir().unwrap();let target=Storage::open(&d.path().join("replica.sqlite")).await.unwrap();let local=target.sync_cursor().await.unwrap();
 target.ingest_revisions(&p,&local.epoch,&source.epoch,s.sync_manifest(&p).await.unwrap(),page.revisions.clone()).await.unwrap();assert_eq!(target.load_project_data(&p,"notebookTools").await.unwrap().unwrap().payload,data);
 let mut other=data.clone();other["notes"][0]["text"]=json!("Another window note");s.save_project_data(&p,"notebookTools",other.clone(),Some(saved.revision_id.clone())).await.unwrap();let mut remote=data.clone();remote["notes"][0]["text"]=json!("Replica note");target.save_project_data(&p,"notebookTools",remote,Some(saved.revision_id)).await.unwrap();let batch=s.pull_revisions(&p,source.clone(),1000).await.unwrap();target.ingest_revisions(&p,&local.epoch,&source.epoch,s.sync_manifest(&p).await.unwrap(),batch.revisions).await.unwrap();let current=target.load_project_data(&p,"notebookTools").await.unwrap().unwrap();assert!(target.save_project_data(&p,"notebookTools",data.clone(),Some(current.revision_id)).await.unwrap_err().contains("Conflict"));let heads=target.project_data_heads(&p,"notebookTools").await.unwrap();assert_eq!(heads.revision_ids.len(),2);target.resolve_project_data(&p,"notebookTools",other,heads.revision_ids).await.unwrap();
 // Incoming source forgery, even in the same batch, rolls back the whole replica.
 let fresh=Storage::open(&d.path().join("forged.sqlite")).await.unwrap();let epoch=fresh.sync_cursor().await.unwrap();let mut forged=page.revisions;let r=forged.iter_mut().find(|r|r.operation=="notebookTools").unwrap();r.payload["reactions"][0]["quote"]=json!("forged");r.checksum=format!("{:x}",Sha256::digest(serde_json::to_string(&r.payload).unwrap().as_bytes()));assert!(fresh.ingest_revisions(&p,&epoch.epoch,&source.epoch,s.sync_manifest(&p).await.unwrap(),forged).await.unwrap_err().contains("does not match"));assert_eq!(fresh.sync_cursor().await.unwrap(),epoch);assert!(fresh.open_project(&p).await.is_err());
}
